<?php
declare(strict_types=1);session_start();
if(empty($_SESSION['instituicao_id'])||($_SESSION['perfil']??'')!=='instituicao'){header('Location: login.php?perfil=instituicao');exit;}
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
$dados=null;
try{require_once __DIR__ . '/db.php';$db=db();$q=$db->prepare('SELECT nome_instituicao,email,telefone,responsavel,cep,logradouro,numero,complemento,bairro,cidade,estado,necessidades,status FROM instituicoes WHERE id=?');$q->execute([(int)$_SESSION['instituicao_id']]);$dados=$q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $e){}
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Painel da instituição — Padrinho Solidário</title><link rel="stylesheet" href="assets/css/style.css"><style>.panel-page{min-height:100vh;padding:40px 18px;background:var(--bg)}.panel-wrap{max-width:900px;margin:auto}.panel-card{margin-top:24px;padding:clamp(22px,4vw,38px);background:var(--surface);border:1px solid var(--border);border-radius:20px;box-shadow:var(--shadow)}.panel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel-item{padding:14px;background:var(--bg);border-radius:12px}.panel-item strong{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}.panel-item p{margin:0;white-space:pre-wrap}.panel-wide{grid-column:1/-1}.panel-status{display:inline-block;padding:7px 12px;border-radius:20px;background:#fff1d6;color:#825414;font-size:12px;font-weight:700}@media(max-width:600px){.panel-grid{grid-template-columns:1fr}.panel-wide{grid-column:auto}}</style></head><body><main class="panel-page"><div class="panel-wrap"><header style="display:flex;justify-content:space-between;align-items:center;gap:12px"><a class="brand" href="index.php"><span class="brand-mark">♥</span><span>Padrinho Solidário</span></a><a class="button button-outline" href="sair.php">Sair</a></header><section class="panel-card"><span class="eyebrow">Área da instituição</span><h1>Bem-vinda(o), <?=e((string)$_SESSION['instituicao_nome'])?></h1><?php if($dados):?><p class="panel-status">Cadastro: <?=e($dados['status'])?></p><p>Este é o resumo dos dados cadastrados pela instituição.</p><div class="panel-grid"><?php $items=['Nome da instituição'=>'nome_instituicao','E-mail'=>'email','Telefone'=>'telefone','Responsável'=>'responsavel','CEP'=>'cep','Endereço'=>'logradouro','Número'=>'numero','Complemento'=>'complemento','Bairro'=>'bairro','Cidade'=>'cidade','Estado'=>'estado'];foreach($items as $label=>$key):?><div class="panel-item"><strong><?=e($label)?></strong><p><?=e((string)$dados[$key])?></p></div><?php endforeach?><div class="panel-item panel-wide"><strong>Necessidades informadas</strong><p><?=e((string)$dados['necessidades'])?></p></div></div><?php else:?><p>Não foi possível carregar os dados cadastrados.</p><?php endif?><p class="privacy-note" style="margin-top:22px">Nesta etapa, o painel apresenta os dados registrados. A gestão de solicitações, atualização cadastral e aprovação institucional serão módulos posteriores.</p></section></div></main></body></html>
